import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{o as n,c as s,e}from"./app-4490560f.js";const t={},i=e(`<h1 id="cmake-跨平台构建系统生成器-c-c-项目标配" tabindex="-1"><a class="header-anchor" href="#cmake-跨平台构建系统生成器-c-c-项目标配" aria-hidden="true">#</a> cmake（跨平台构建系统生成器，C/C++ 项目标配）</h1><blockquote><p>Homebrew 版本 4.2.0 ｜ 主页：见官方文档 ｜ 安装：<code>brew install cmake</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>CMake 是一个<strong>跨平台的构建系统生成器</strong>。它本身不直接编译代码，而是读取 <code>CMakeLists.txt</code> 配置文件，为你生成平台原生的构建文件——在 Linux/macOS 上生成 Makefile，在 Windows 上生成 Visual Studio 工程文件。这样同一份源码就能在多个平台上用同一套构建逻辑编译。</p><p>它解决的问题是：手写 Makefile 或项目文件非常繁琐、难以维护，且无法跨平台复用。CMake 用简洁的声明式语法描述「项目有什么目标、依赖什么库、编译选项是什么」，然后自动生成对应平台的构建脚本，是当前 C/C++ 项目的事实标准。典型应用场景包括：管理大型 C/C++ 项目、自动发现并链接第三方依赖、配合 IDE（CLion、VS Code、Qt Creator）使用、生成安装/打包规则等。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>使用 Homebrew 安装、升级、卸载：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> cmake

<span class="token comment"># 升级（保持最新版本）</span>
brew upgrade cmake

<span class="token comment"># 卸载</span>
brew uninstall cmake

<span class="token comment"># 查看已安装版本</span>
cmake <span class="token parameter variable">--version</span>

<span class="token comment"># 查看 brew 管理的 cmake 详情（安装路径、依赖等）</span>
brew info cmake
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证安装成功，运行 <code>cmake --version</code>，输出应包含版本号 <code>4.2.0</code> 以及 <code>Make/CMake/CTest/CPack</code> 组件信息，例如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cmake version 4.2.0

CMake suite maintained and supported by Kitware (kitware.com/cmake).
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>提示</strong>：Homebrew 装的 CMake 可能不是最新（brew 默认跟踪稳定版）。若需要新版本或 CI 里用固定版本，可用 <code>brew install cmake@3</code> 系列，或用 <code>pipx</code>/官方二进制安装最新版。</p></blockquote><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数 / 说明</th><th>示例</th></tr></thead><tbody><tr><td><code>cmake --version</code></td><td>查看版本号，验证安装</td><td><code>cmake --version</code></td></tr><tr><td><code>cmake -S &lt;源目录&gt; -B &lt;构建目录&gt;</code></td><td>配置项目，生成构建文件（4.0+ 推荐写法）</td><td><code>cmake -S . -B build</code></td></tr><tr><td><code>cmake --build &lt;构建目录&gt;</code></td><td>编译构建目录里的项目</td><td><code>cmake --build build</code></td></tr><tr><td><code>cmake --install &lt;构建目录&gt;</code></td><td>安装到指定前缀</td><td><code>cmake --install build --prefix /usr/local</code></td></tr><tr><td><code>cmake -G &lt;生成器&gt;</code></td><td>指定生成器（如 Unix Makefiles、Ninja、Xcode）</td><td><code>cmake -S . -B build -G Ninja</code></td></tr><tr><td><code>cmake -D&lt;变量&gt;=&lt;值&gt;</code></td><td>定义/覆盖缓存变量（如开关选项、安装路径）</td><td><code>cmake -S . -B build -DCMAKE_BUILD_TYPE=Release</code></td></tr><tr><td><code>cmake --build build --target install</code></td><td>只构建指定目标</td><td><code>cmake --build build --target my_app</code></td></tr><tr><td><code>ctest</code></td><td>运行项目测试（配合 CMake 的 add_test）</td><td><code>cd build &amp;&amp; ctest</code></td></tr><tr><td><code>cpack</code></td><td>打包生成安装包（deb/rpm/dmg）</td><td><code>cpack -G DEB</code></td></tr><tr><td><code>cmake -L build</code></td><td>列出缓存中所有变量</td><td><code>cmake -L build</code></td></tr><tr><td><code>cmake --build build --clean-first</code></td><td>清理后重新编译</td><td><code>cmake --build build --clean-first</code></td></tr><tr><td><code>cmake --build build --parallel 8</code></td><td>指定并行编译线程数</td><td><code>cmake --build build --parallel 8</code></td></tr><tr><td><code>cmake -LAH build</code></td><td>列出缓存全部变量（含高级与帮助）</td><td><code>cmake -LAH build</code></td></tr><tr><td><code>cmake --fresh</code></td><td>清空缓存重新配置</td><td><code>cmake -S . -B build --fresh</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-最小-c-项目-hello-world" tabindex="-1"><a class="header-anchor" href="#示例-1-最小-c-项目-hello-world" aria-hidden="true">#</a> 示例 1：最小 C 项目（Hello World）</h3><p>这是最基础、最常见的用法，从源码编译一个可执行程序。</p><p><strong>1. 准备项目文件</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">mkdir</span> hello <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> hello
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>创建源码 <code>hello.c</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> hello.c <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;stdio.h&gt;

int main(void) {
    printf(&quot;Hello, CMake!\\n&quot;);
    return 0;
}
EOF</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>创建构建配置 <code>CMakeLists.txt</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> CMakeLists.txt <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
cmake_minimum_required(VERSION 3.20)
project(Hello C)

add_executable(hello hello.c)
EOF</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 配置并编译</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># -S 指定源目录，-B 指定构建目录（源码与构建产物分离，保持目录干净）</span>
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build
cmake <span class="token parameter variable">--build</span> build
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 运行看结果</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>./build/hello
<span class="token comment"># 输出：Hello, CMake!</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-多文件-链接第三方库-openmp" tabindex="-1"><a class="header-anchor" href="#示例-2-多文件-链接第三方库-openmp" aria-hidden="true">#</a> 示例 2：多文件 + 链接第三方库（OpenMP）</h3><p>展示 C++ 项目、多源文件、链接系统库的常见结构。</p><p><strong>1. 准备项目文件</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">mkdir</span> demo <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> demo
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>创建 <code>main.cpp</code> 和 <code>math_utils.cpp</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> main.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;iostream&gt;
#include &quot;math_utils.hpp&quot;

int main() {
    std::cout &lt;&lt; &quot;sum(3,4) = &quot; &lt;&lt; add(3, 4) &lt;&lt; std::endl;
    return 0;
}
EOF</span>

<span class="token function">cat</span> <span class="token operator">&gt;</span> math_utils.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &quot;math_utils.hpp&quot;

int add(int a, int b) { return a + b; }
EOF</span>

<span class="token function">cat</span> <span class="token operator">&gt;</span> math_utils.hpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#pragma once
int add(int a, int b);
EOF</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>创建 <code>CMakeLists.txt</code>，用 <code>target_include_directories</code> 指定头文件搜索路径：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> CMakeLists.txt <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
cmake_minimum_required(VERSION 3.20)
project(Demo CXX)

add_executable(demo main.cpp math_utils.cpp)
target_include_directories(demo PRIVATE \${CMAKE_CURRENT_SOURCE_DIR})
EOF</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 配置并编译（指定 Release 优化）</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release
cmake <span class="token parameter variable">--build</span> build
./build/demo
<span class="token comment"># 输出：sum(3,4) = 7</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-用-cmake-构建-git-依赖-fetchcontent" tabindex="-1"><a class="header-anchor" href="#示例-3-用-cmake-构建-git-依赖-fetchcontent" aria-hidden="true">#</a> 示例 3：用 CMake 构建 Git 依赖（FetchContent）</h3><p>当项目依赖一个 Git 仓库时，CMake 3.11+ 的 <code>FetchContent</code> 能在配置阶段自动拉取并构建。</p><p><strong>1. 准备项目文件</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">mkdir</span> fetchdemo <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> fetchdemo
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>创建 <code>main.cpp</code> 和 <code>CMakeLists.txt</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> main.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;iostream&gt;
#include &lt;fmt/core.h&gt;

int main() {
    std::cout &lt;&lt; fmt::format(&quot;FetchContent demo, answer = {}&quot;, 42) &lt;&lt; std::endl;
    return 0;
}
EOF</span>

<span class="token function">cat</span> <span class="token operator">&gt;</span> CMakeLists.txt <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
cmake_minimum_required(VERSION 3.20)
project(FetchDemo CXX)

include(FetchContent)
FetchContent_Declare(
  fmt
  GIT_REPOSITORY https://github.com/fmtlib/fmt.git
  GIT_TAG 11.0.2
)
FetchContent_MakeAvailable(fmt)

add_executable(fetchdemo main.cpp)
target_link_libraries(fetchdemo PRIVATE fmt::fmt)
EOF</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 配置（首次会联网拉取 fmt 库）、编译并运行</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build
cmake <span class="token parameter variable">--build</span> build
./build/fetchdemo
<span class="token comment"># 输出：FetchContent demo, answer = 42</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-用-ninja-加速编译" tabindex="-1"><a class="header-anchor" href="#_1-用-ninja-加速编译" aria-hidden="true">#</a> 1. 用 Ninja 加速编译</h3><p>默认的 Unix Makefiles 生成器是单线程的，改用 Ninja 可自动利用多核并显著提速（构建时加 <code>-j</code> 控制并行度）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>brew <span class="token function">install</span> ninja
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-G</span> Ninja
cmake <span class="token parameter variable">--build</span> build <span class="token parameter variable">-j8</span>   <span class="token comment"># 8 线程并行编译</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-常用缓存变量与环境变量" tabindex="-1"><a class="header-anchor" href="#_2-常用缓存变量与环境变量" aria-hidden="true">#</a> 2. 常用缓存变量与环境变量</h3><ul><li><code>-DCMAKE_BUILD_TYPE=Debug|Release|RelWithDebInfo</code>：指定构建类型（影响优化级别和调试信息）。</li><li><code>-DCMAKE_INSTALL_PREFIX=&lt;路径&gt;</code>：设置安装前缀，等价于 <code>cmake --install build --prefix &lt;路径&gt;</code>。</li><li><code>-DCMAKE_PREFIX_PATH=&lt;路径&gt;</code>：额外的库搜索路径，找不到依赖时很常用。</li><li><code>-DCMAKE_EXPORT_COMPILE_COMMANDS=ON</code>：生成 <code>compile_commands.json</code>，供 clangd、IDE 的「转到定义」等功能使用。</li><li><code>-DCMAKE_CXX_STANDARD=17</code> / <code>-DCMAKE_C_STANDARD=11</code>：全局设置语言标准（配合 <code>set</code> 或 target 级 <code>cxx_std_17</code> 使用）。</li><li><code>-DCMAKE_TOOLCHAIN_FILE=&lt;路径&gt;</code>：指定交叉编译工具链文件（见「跨平台编译」一节）。</li><li><code>-DCMAKE_GENERATOR=Ninja</code>：也可以在缓存里固化生成器，但更推荐 <code>-G</code> 每次显式传。</li><li><code>CC</code> / <code>CXX</code> 环境变量：指定编译器，例如 <code>CC=clang CXX=clang++ cmake -S . -B build</code>。</li><li><code>CMAKE_PREFIX_PATH</code> 环境变量：等价于 <code>-DCMAKE_PREFIX_PATH</code>，但可在 <code>.bashrc</code>/<code>.zshrc</code> 里长期导出，省去每次传参。</li><li><code>CMAKE_CXX_FLAGS</code> / <code>CMAKE_C_FLAGS</code>：追加编译标志，如 <code>-DCMAKE_CXX_FLAGS=&quot;-Wall -Wextra&quot;</code>。</li><li><code>CMAKE_MAKE_PROGRAM</code>：生成器找不到 <code>ninja</code>/<code>make</code> 时可显式指定其绝对路径。</li><li>清理缓存：删掉 <code>build/</code> 目录重新配置即可，不需要手动清缓存；<code>cmake --fresh</code> 可在不删目录的情况下清空缓存重配。</li></ul><p><strong>推荐的一行 Release 配置</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-G</span> Ninja <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_EXPORT_COMPILE_COMMANDS</span><span class="token operator">=</span>ON <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_PREFIX_PATH</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span>brew <span class="token parameter variable">--prefix</span><span class="token variable">)</span></span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-与-ide-搭配" tabindex="-1"><a class="header-anchor" href="#_3-与-ide-搭配" aria-hidden="true">#</a> 3. 与 IDE 搭配</h3><ul><li><strong>VS Code</strong>：安装 CMake Tools 扩展后，打开含 <code>CMakeLists.txt</code> 的目录即可自动配置、编译、调试。</li><li><strong>CLion</strong>：直接打开 <code>CMakeLists.txt</code> 作为项目文件。</li><li><strong>Qt Creator</strong>：新建项目时选择「CMake 项目」。</li><li><strong>生成 IDE 工程</strong>：macOS 上可用 <code>cmake -G Xcode</code> 生成 Xcode 工程，Windows 上 <code>cmake -G &quot;Visual Studio 17 2022&quot;</code>。</li><li><strong>配合 clangd</strong>：开启 <code>-DCMAKE_EXPORT_COMPILE_COMMANDS=ON</code>，再把生成的 <code>build/compile_commands.json</code> 软链到源码根目录，clangd 即可理解所有 include 与编译标志：<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">ln</span> <span class="token parameter variable">-sf</span> build/compile_commands.json compile_commands.json
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li></ul><h3 id="_4-模块化-cmakelists-子目录与函数" tabindex="-1"><a class="header-anchor" href="#_4-模块化-cmakelists-子目录与函数" aria-hidden="true">#</a> 4. 模块化 CMakeLists：子目录与函数</h3><p>大型项目不应把所有内容塞进一个文件。用 <code>add_subdirectory</code> 组织模块，用 <code>function()</code>/<code>macro()</code> 抽取可复用逻辑：</p><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token comment"># 根 CMakeLists.txt</span>
<span class="token keyword">cmake_minimum_required</span><span class="token punctuation">(</span><span class="token property">VERSION</span> <span class="token number">3.20</span><span class="token punctuation">)</span>
<span class="token keyword">project</span><span class="token punctuation">(</span>MyApp CXX<span class="token punctuation">)</span>

<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_CXX_STANDARD</span> <span class="token number">17</span><span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_CXX_STANDARD_REQUIRED</span> <span class="token boolean">ON</span><span class="token punctuation">)</span>

<span class="token comment"># 复用函数：统一为可执行目标设置编译警告</span>
<span class="token keyword">function</span><span class="token punctuation">(</span>enable_warnings target<span class="token punctuation">)</span>
    <span class="token keyword">target_compile_options</span><span class="token punctuation">(</span><span class="token punctuation">\${</span>target<span class="token punctuation">}</span> <span class="token namespace">PRIVATE</span> -Wall -Wextra -Wpedantic<span class="token punctuation">)</span>
<span class="token keyword">endfunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span>

<span class="token keyword">add_subdirectory</span><span class="token punctuation">(</span>core<span class="token punctuation">)</span>        <span class="token comment"># core/CMakeLists.txt</span>
<span class="token keyword">add_subdirectory</span><span class="token punctuation">(</span>app<span class="token punctuation">)</span>         <span class="token comment"># app/CMakeLists.txt</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token comment"># core/CMakeLists.txt —— 生成一个静态库</span>
<span class="token keyword">add_library</span><span class="token punctuation">(</span>core <span class="token namespace">STATIC</span> core.cpp<span class="token punctuation">)</span>
<span class="token keyword">target_include_directories</span><span class="token punctuation">(</span>core <span class="token namespace">PUBLIC</span> <span class="token punctuation">\${</span><span class="token variable">CMAKE_CURRENT_SOURCE_DIR</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token comment"># app/CMakeLists.txt —— 生成主程序并链接库</span>
<span class="token keyword">add_executable</span><span class="token punctuation">(</span>app main.cpp<span class="token punctuation">)</span>
<span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>app <span class="token namespace">PRIVATE</span> core<span class="token punctuation">)</span>
<span class="token function">enable_warnings</span><span class="token punctuation">(</span>app<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-用-find-package-发现第三方依赖" tabindex="-1"><a class="header-anchor" href="#_5-用-find-package-发现第三方依赖" aria-hidden="true">#</a> 5. 用 find_package 发现第三方依赖</h3><p><code>find_package</code> 是 CMake 发现已安装库的官方方式。它优先找 <code>&lt;pkg&gt;Config.cmake</code>（现代库），找不到时退化为找 <code>Find&lt;pkg&gt;.cmake</code> 模块。</p><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token keyword">find_package</span><span class="token punctuation">(</span>OpenMP REQUIRED<span class="token punctuation">)</span>
<span class="token keyword">if</span><span class="token punctuation">(</span>OpenMP_CXX_FOUND<span class="token punctuation">)</span>
    <span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>demo <span class="token namespace">PRIVATE</span> <span class="token inserted class-name">OpenMP::OpenMP_CXX</span><span class="token punctuation">)</span>
<span class="token keyword">endif</span><span class="token punctuation">(</span><span class="token punctuation">)</span>

<span class="token keyword">find_package</span><span class="token punctuation">(</span>fmt QUIET<span class="token punctuation">)</span>
<span class="token keyword">if</span><span class="token punctuation">(</span>fmt_FOUND<span class="token punctuation">)</span>
    <span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>demo <span class="token namespace">PRIVATE</span> <span class="token inserted class-name">fmt::fmt</span><span class="token punctuation">)</span>
<span class="token keyword">else</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token keyword">message</span><span class="token punctuation">(</span>WARNING <span class="token string">&quot;fmt not found, falling back&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">endif</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在 macOS 上配合 Homebrew 使用很关键：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 让 CMake 能搜到 brew 安装的库</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">CMAKE_PREFIX_PATH</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span>brew <span class="token parameter variable">--prefix</span><span class="token variable">)</span></span>&quot;</span>
<span class="token comment"># 或对单个库</span>
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DCMAKE_PREFIX_PATH</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span>brew <span class="token parameter variable">--prefix</span> <span class="token function">fmt</span><span class="token variable">)</span></span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常见 <code>find_package</code> 报错与处理见「六、常见问题」第 4 条。</p><h3 id="_6-测试与打包-ctest-cpack" tabindex="-1"><a class="header-anchor" href="#_6-测试与打包-ctest-cpack" aria-hidden="true">#</a> 6. 测试与打包（CTest + CPack）</h3><p>在 <code>CMakeLists.txt</code> 中加入测试规则，即可用 <code>ctest</code> 一键跑测试：</p><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token keyword">include</span><span class="token punctuation">(</span>CTest<span class="token punctuation">)</span>                 <span class="token comment"># 比 enable_testing() 更完善，会注册 BUILD_TESTING 开关</span>
<span class="token keyword">if</span><span class="token punctuation">(</span>BUILD_TESTING<span class="token punctuation">)</span>
    <span class="token keyword">add_executable</span><span class="token punctuation">(</span>unit_tests test_main.cpp<span class="token punctuation">)</span>
    <span class="token keyword">add_test</span><span class="token punctuation">(</span><span class="token property">NAME</span> unit_tests COMMAND unit_tests<span class="token punctuation">)</span>
    <span class="token comment"># 用 GTest 时更常见的是：</span>
    <span class="token comment"># enable_testing()</span>
    <span class="token comment"># gtest_discover_tests(unit_tests)</span>
<span class="token keyword">endif</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">cd</span> build <span class="token operator">&amp;&amp;</span> ctest --output-on-failure
<span class="token comment"># 运行单个测试 / 按正则筛选</span>
ctest <span class="token parameter variable">-R</span> unit_tests
ctest <span class="token parameter variable">-R</span> <span class="token string">&quot;^test_math&quot;</span> --output-on-failure
<span class="token comment"># 设置超时（秒）与并行</span>
ctest <span class="token parameter variable">--timeout</span> <span class="token number">30</span> <span class="token parameter variable">-j8</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>CPack 打包：</p><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token keyword">set</span><span class="token punctuation">(</span>CPACK_PACKAGE_NAME <span class="token string">&quot;myapp&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CPACK_PACKAGE_VERSION</span> <span class="token string">&quot;1.0.0&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span>CPACK_PACKAGE_CONTACT <span class="token string">&quot;dev@example.com&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span>CPACK_GENERATOR <span class="token string">&quot;TGZ;DragNDrop&quot;</span><span class="token punctuation">)</span>   <span class="token comment"># 默认同时生成多种</span>
<span class="token keyword">include</span><span class="token punctuation">(</span>CPack<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build
cmake <span class="token parameter variable">--build</span> build
cpack <span class="token parameter variable">--config</span> build/CPackConfig.cmake <span class="token parameter variable">-G</span> DEB   <span class="token comment"># Debian/Ubuntu</span>
cpack <span class="token parameter variable">--config</span> build/CPackConfig.cmake <span class="token parameter variable">-G</span> DragNDrop  <span class="token comment"># macOS .dmg</span>
cpack <span class="token parameter variable">--config</span> build/CPackConfig.cmake <span class="token parameter variable">-G</span> RPM   <span class="token comment"># Fedora/RHEL</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-跨平台编译-交叉编译" tabindex="-1"><a class="header-anchor" href="#_7-跨平台编译-交叉编译" aria-hidden="true">#</a> 7. 跨平台编译（交叉编译）</h3><p>用<strong>工具链文件</strong>（toolchain file）描述目标平台，是 CMake 交叉编译的标准做法：</p><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token comment"># cross-arm64.cmake</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_SYSTEM_NAME</span> Linux<span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_SYSTEM_PROCESSOR</span> aarch64<span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_C_COMPILER</span> aarch64-linux-gnu-gcc<span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_CXX_COMPILER</span> aarch64-linux-gnu-g++<span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_FIND_ROOT_PATH</span> /usr/aarch64-linux-gnu<span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_FIND_ROOT_PATH_MODE_PROGRAM</span> NEVER<span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_FIND_ROOT_PATH_MODE_LIBRARY</span> ONLY<span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_FIND_ROOT_PATH_MODE_INCLUDE</span> ONLY<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build-arm64 <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span>cross-arm64.cmake
cmake <span class="token parameter variable">--build</span> build-arm64
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>macOS 上做 iOS 交叉编译用 Xcode 生成器即可：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build-ios <span class="token parameter variable">-G</span> Xcode <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_SYSTEM_NAME</span><span class="token operator">=</span>iOS <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_OSX_SYSROOT</span><span class="token operator">=</span>iphoneos <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_OSX_ARCHITECTURES</span><span class="token operator">=</span><span class="token string">&quot;arm64&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>同机多架构（universal 二进制）</strong>——macOS 上直接指定多个架构：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DCMAKE_OSX_ARCHITECTURES</span><span class="token operator">=</span><span class="token string">&quot;arm64;x86_64&quot;</span>
cmake <span class="token parameter variable">--build</span> build
lipo <span class="token parameter variable">-info</span> build/myapp   <span class="token comment"># 查看支持的架构</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="常见报错" tabindex="-1"><a class="header-anchor" href="#常见报错" aria-hidden="true">#</a> 常见报错</h3><ol><li><p><strong><code>CMake Error: The source directory ... does not appear to contain CMakeLists.txt</code></strong><br> 在错误的目录执行了 <code>cmake -S</code>，检查 <code>-S</code> 指向的目录里确实有 <code>CMakeLists.txt</code>。</p></li><li><p><strong><code>fatal error: &#39;xxx.h&#39; file not found</code></strong><br> 头文件找不到。用 <code>target_include_directories</code> 显式声明头文件目录，或确认第三方库路径已通过 <code>-DCMAKE_PREFIX_PATH</code> 指定。</p></li><li><p><strong><code>undefined reference to ...</code></strong><br> 链接错误，说明声明了函数但没链接到实现库。用 <code>target_link_libraries</code> 补上对应的库（如 <code>m</code>、<code>pthread</code>、第三方库）。</p></li><li><p><strong><code>Could not find a package configuration file provided by &quot;xxx&quot;</code></strong><br> CMake 没找到 <code>find_package</code> 要求的包。用 <code>brew install xxx</code> 安装，或用 <code>-DCMAKE_PREFIX_PATH</code> 指定其安装路径。注意：如果安装包里只有 <code>xxx.pc</code>（pkg-config 风格）而没有 <code>xxxConfig.cmake</code>，可先用 <code>pkg-config</code> 探测，或给 <code>find_package</code> 传 <code>xxx_VERSION</code>/<code>REQUIRED</code> 之外的提示。排查时先确认：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>brew info xxx        <span class="token comment"># 看安装路径</span>
<span class="token function">find</span> <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span>brew <span class="token parameter variable">--prefix</span><span class="token variable">)</span></span>&quot;</span> <span class="token parameter variable">-name</span> <span class="token string">&quot;*Config.cmake&quot;</span> <span class="token parameter variable">-o</span> <span class="token parameter variable">-name</span> <span class="token string">&quot;Find*.cmake&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-i</span> xxx
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>编译器版本过旧</strong><br> 新版 CMake（尤其 4.x）要求较新的编译器和标准。升级编译器（macOS 用 <code>xcode-select --install</code> 装/更新 Command Line Tools）或降低 <code>cmake_minimum_required</code> 版本。</p></li><li><p><strong><code>CMakeCache.txt: error reading cache file</code> 或缓存损坏</strong><br> 手动编辑 <code>CMakeCache.txt</code> 或用不同编译器/路径复用了同一构建目录。删掉整个 <code>build/</code> 重新配置最稳妥。</p></li><li><p><strong><code>Policy CMP0077 is not set</code> 等 Policy 警告</strong><br> 新版 CMake 变更了旧默认行为。可在 <code>CMakeLists.txt</code> 顶部显式声明：</p><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token keyword">cmake_policy</span><span class="token punctuation">(</span>SET CMP0077 NEW<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><p><strong><code>ld: library not found for -l&lt;name&gt;</code>（macOS 特有）</strong><br> 链接器找不到库文件，常见于 brew 安装的库在非默认路径。加 <code>-DCMAKE_PREFIX_PATH=&quot;$(brew --prefix)&quot;</code>，或用 <code>-L</code>/<code>target_link_directories</code> 显式指向库目录。</p></li><li><p><strong><code>ninja: error: loading &#39;build.ninja&#39;: No such file</code></strong><br> 直接用 <code>ninja</code> 但还没 <code>cmake -G Ninja</code> 配置过。先跑配置步骤，或 <code>cmake --build build</code> 让它走标准流程。</p></li><li><p><strong><code>--build</code> 反复重编全部文件（增量失效）</strong><br> 通常因为时间戳/依赖变化异常，或跨了不同 <code>CMAKE_BUILD_TYPE</code> 复用了同一构建目录。用不同构建目录区分不同配置（如 <code>build-debug</code>、<code>build-release</code>）。</p></li></ol><h3 id="注意要点" tabindex="-1"><a class="header-anchor" href="#注意要点" aria-hidden="true">#</a> 注意要点</h3><ul><li><strong><code>cmake_minimum_required</code> 放第一行</strong>：声明 CMake 最低版本，避免旧版误用新语法。</li><li><strong>不要污染源码目录</strong>：始终用 <code>-B</code> 指定独立构建目录，避免 <code>build/</code> 产物混进源码，否则切换平台/构建类型时容易踩坑。</li><li><strong>区分路径</strong>：<code>CMAKE_CURRENT_SOURCE_DIR</code> 是源码目录，<code>CMAKE_CURRENT_BINARY_DIR</code> 是构建目录，配置文件的绝对路径引用务必用这两个变量，不要硬编码。</li><li><strong><code>find_package</code> 依赖 <code>Config.cmake</code></strong>：很多库需 <code>brew install</code> 并配合 <code>-DCMAKE_PREFIX_PATH=$(brew --prefix)</code> 才能被正确找到。</li><li><strong>清理构建目录</strong>：缓存异常时，删 <code>build/</code> 比手动改 <code>CMakeCache.txt</code> 更可靠。</li><li><strong><code>FetchContent</code> 会执行远程仓库的 CMake 代码</strong>：拉取前务必确认仓库可信。可固定 <code>GIT_TAG</code>（commit SHA 而非分支名）保证可复现、防漂移。</li><li><strong>Debug 与 Release 别共用构建目录</strong>：二者 <code>CMAKE_BUILD_TYPE</code> 不同，混合使用会互相覆盖缓存，产出异常结果。用 <code>build-debug</code>/<code>build-release</code> 分开。</li><li><strong>并行度不要盲目拉满</strong>：<code>-j</code> 超过核数反而因内存/IO 瓶颈变慢。用 <code>nproc</code>（Linux）/<code>sysctl -n hw.ncpu</code>（macOS）取核数再乘 1.5 左右为经验值。</li><li><strong>注意 <code>find_package</code> 与 <code>FetchContent</code> 的冲突</strong>：同名依赖若既被 <code>find_package</code> 又由 <code>FetchContent</code> 提供，需用 <code>FetchContent_MakeAvailable</code> 的覆盖逻辑处理，否则会出现「重复定义/类型冲突」类诡异报错。</li><li><strong>头文件里 <code>#pragma once</code> 优于传统 <code>#ifndef</code> 守卫</strong>：避免重复包含，也让 CMake 目标间依赖更直观。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-与-ninja-配合-更快更清晰的增量构建" tabindex="-1"><a class="header-anchor" href="#_1-与-ninja-配合-更快更清晰的增量构建" aria-hidden="true">#</a> 1. 与 Ninja 配合：更快更清晰的增量构建</h3><p>Ninja 是现代 CMake 的首选生成器，增量构建准确、并行度高：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>brew <span class="token function">install</span> ninja
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-G</span> Ninja <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Debug
cmake <span class="token parameter variable">--build</span> build <span class="token parameter variable">-j8</span>

<span class="token comment"># 只看改动目标（Ninja 输出简洁）</span>
ninja <span class="token parameter variable">-C</span> build my_app
<span class="token comment"># 图形化依赖图（需 graphviz）</span>
ninja <span class="token parameter variable">-C</span> build <span class="token parameter variable">-t</span> graph <span class="token operator">|</span> dot <span class="token parameter variable">-Tpng</span> <span class="token parameter variable">-o</span> build-graph.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ninja 与 Makefile 的核心差异是<strong>由 CMake 直接生成</strong>（不套一层 Make），增量判定更精确，改一个头文件通常只重编直接依赖它的文件。</p><h3 id="_2-用-makefile-包装常用命令" tabindex="-1"><a class="header-anchor" href="#_2-用-makefile-包装常用命令" aria-hidden="true">#</a> 2. 用 Makefile 包装常用命令</h3><p>很多人习惯用顶层 Makefile 简化记忆，把长命令收进目标：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># 顶层 Makefile</span>
BUILD_DIR <span class="token operator">?=</span> build

<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> configure build test install clean run

<span class="token target symbol">configure</span><span class="token punctuation">:</span>
	cmake -S . -B <span class="token variable">$</span><span class="token punctuation">(</span>BUILD_DIR<span class="token punctuation">)</span> -G Ninja -DCMAKE_BUILD_TYPE<span class="token operator">=</span>Release

<span class="token target symbol">build</span><span class="token punctuation">:</span> configure
	cmake --build <span class="token variable">$</span><span class="token punctuation">(</span>BUILD_DIR<span class="token punctuation">)</span> -j8

<span class="token target symbol">test</span><span class="token punctuation">:</span> build
	cd <span class="token variable">$</span><span class="token punctuation">(</span>BUILD_DIR<span class="token punctuation">)</span> &amp;&amp; ctest --output-on-failure

<span class="token target symbol">install</span><span class="token punctuation">:</span> build
	cmake --install <span class="token variable">$</span><span class="token punctuation">(</span>BUILD_DIR<span class="token punctuation">)</span>

<span class="token target symbol">run</span><span class="token punctuation">:</span> build
	./<span class="token variable">$</span><span class="token punctuation">(</span>BUILD_DIR<span class="token punctuation">)</span>/app

<span class="token target symbol">clean</span><span class="token punctuation">:</span>
	rm -rf <span class="token variable">$</span><span class="token punctuation">(</span>BUILD_DIR<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用法：<code>make configure</code>、<code>make build</code>、<code>make test</code>、<code>make install</code>、<code>make clean</code>。</p><h3 id="_3-脚本自动化-一键配置-构建-测试" tabindex="-1"><a class="header-anchor" href="#_3-脚本自动化-一键配置-构建-测试" aria-hidden="true">#</a> 3. 脚本自动化：一键配置 + 构建 + 测试</h3><p>用一个 shell 脚本串联标准流程，并做健壮性处理：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token builtin class-name">set</span> <span class="token parameter variable">-euo</span> pipefail          <span class="token comment"># 出错即停、变量未定义即报错</span>

<span class="token assign-left variable">BUILD_DIR</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${1<span class="token operator">:-</span>build}</span>&quot;</span>
<span class="token assign-left variable">BUILD_TYPE</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${BUILD_TYPE<span class="token operator">:-</span>Release}</span>&quot;</span>
<span class="token assign-left variable">CORES</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${CORES<span class="token operator">:-</span>$(sysctl -n hw.ncpu 2&gt;<span class="token operator">/</span>dev<span class="token operator">/</span>null || nproc)}</span>&quot;</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&gt;&gt; Configuring (<span class="token variable">$BUILD_TYPE</span>) into <span class="token variable">$BUILD_DIR</span>&quot;</span>
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> <span class="token string">&quot;<span class="token variable">$BUILD_DIR</span>&quot;</span> <span class="token parameter variable">-G</span> Ninja <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$BUILD_TYPE</span>&quot;</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_EXPORT_COMPILE_COMMANDS</span><span class="token operator">=</span>ON

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&gt;&gt; Building with <span class="token variable">$CORES</span> jobs&quot;</span>
cmake <span class="token parameter variable">--build</span> <span class="token string">&quot;<span class="token variable">$BUILD_DIR</span>&quot;</span> -j<span class="token string">&quot;<span class="token variable">$CORES</span>&quot;</span>

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&gt;&gt; Running tests&quot;</span>
<span class="token builtin class-name">cd</span> <span class="token string">&quot;<span class="token variable">$BUILD_DIR</span>&quot;</span> <span class="token operator">&amp;&amp;</span> ctest --output-on-failure

<span class="token builtin class-name">echo</span> <span class="token string">&quot;&gt;&gt; All done.&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-批量处理-遍历子项目-多个配置" tabindex="-1"><a class="header-anchor" href="#_4-批量处理-遍历子项目-多个配置" aria-hidden="true">#</a> 4. 批量处理：遍历子项目/多个配置</h3><p>当工作区含多个独立 CMake 项目时，用循环批量配置构建：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token keyword">for</span> <span class="token for-or-select variable">proj</span> <span class="token keyword">in</span> core lib1 lib2 app<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== Building <span class="token variable">$proj</span> ===&quot;</span>
  cmake <span class="token parameter variable">-S</span> <span class="token string">&quot;<span class="token variable">$proj</span>&quot;</span> <span class="token parameter variable">-B</span> <span class="token string">&quot;<span class="token variable">$proj</span>/build&quot;</span> <span class="token parameter variable">-G</span> Ninja <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release
  cmake <span class="token parameter variable">--build</span> <span class="token string">&quot;<span class="token variable">$proj</span>/build&quot;</span> <span class="token parameter variable">-j8</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>或对同一项目批量产出多套配置：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token keyword">for</span> <span class="token for-or-select variable">bt</span> <span class="token keyword">in</span> Debug Release<span class="token punctuation">;</span> <span class="token keyword">do</span>
  cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> <span class="token string">&quot;build-<span class="token variable">$bt</span>&quot;</span> <span class="token parameter variable">-G</span> Ninja <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$bt</span>&quot;</span>
  cmake <span class="token parameter variable">--build</span> <span class="token string">&quot;build-<span class="token variable">$bt</span>&quot;</span> <span class="token parameter variable">-j8</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-ci-集成-github-actions-gitlab-ci" tabindex="-1"><a class="header-anchor" href="#_5-ci-集成-github-actions-gitlab-ci" aria-hidden="true">#</a> 5. CI 集成（GitHub Actions / GitLab CI）</h3><p>CMake 项目在 CI 里的标准套路：装工具 → 配置 → 构建 → 测试 → 打包。</p><p><strong>GitHub Actions</strong>（<code>.github/workflows/ci.yml</code>）：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> CI
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">,</span> pull_request<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">build</span><span class="token punctuation">:</span>
    <span class="token key atrule">strategy</span><span class="token punctuation">:</span>
      <span class="token key atrule">matrix</span><span class="token punctuation">:</span>
        <span class="token key atrule">os</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>ubuntu<span class="token punctuation">-</span>latest<span class="token punctuation">,</span> macos<span class="token punctuation">-</span>latest<span class="token punctuation">,</span> windows<span class="token punctuation">-</span>latest<span class="token punctuation">]</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> matrix.os <span class="token punctuation">}</span><span class="token punctuation">}</span>
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install deps (Linux)
        <span class="token key atrule">if</span><span class="token punctuation">:</span> runner.os == &#39;Linux&#39;
        <span class="token key atrule">run</span><span class="token punctuation">:</span> sudo apt<span class="token punctuation">-</span>get update <span class="token important">&amp;&amp;</span> sudo apt<span class="token punctuation">-</span>get install <span class="token punctuation">-</span>y ninja<span class="token punctuation">-</span>build
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install deps (macOS)
        <span class="token key atrule">if</span><span class="token punctuation">:</span> runner.os == &#39;macOS&#39;
        <span class="token key atrule">run</span><span class="token punctuation">:</span> brew install ninja
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Configure
        <span class="token key atrule">run</span><span class="token punctuation">:</span> cmake <span class="token punctuation">-</span>S . <span class="token punctuation">-</span>B build <span class="token punctuation">-</span>G Ninja <span class="token punctuation">-</span>DCMAKE_BUILD_TYPE=Release
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build
        <span class="token key atrule">run</span><span class="token punctuation">:</span> cmake <span class="token punctuation">-</span><span class="token punctuation">-</span>build build <span class="token punctuation">-</span>j2
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Test
        <span class="token key atrule">run</span><span class="token punctuation">:</span> ctest <span class="token punctuation">-</span><span class="token punctuation">-</span>test<span class="token punctuation">-</span>dir build <span class="token punctuation">-</span><span class="token punctuation">-</span>output<span class="token punctuation">-</span>on<span class="token punctuation">-</span>failure
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>GitLab CI</strong>（<code>.gitlab-ci.yml</code>）：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">image</span><span class="token punctuation">:</span> gcc<span class="token punctuation">:</span>latest
<span class="token key atrule">before_script</span><span class="token punctuation">:</span>
  <span class="token punctuation">-</span> apt<span class="token punctuation">-</span>get update <span class="token important">&amp;&amp;</span> apt<span class="token punctuation">-</span>get install <span class="token punctuation">-</span>y ninja<span class="token punctuation">-</span>build
<span class="token key atrule">build</span><span class="token punctuation">:</span>
  <span class="token key atrule">stage</span><span class="token punctuation">:</span> build
  <span class="token key atrule">script</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> cmake <span class="token punctuation">-</span>S . <span class="token punctuation">-</span>B build <span class="token punctuation">-</span>G Ninja <span class="token punctuation">-</span>DCMAKE_BUILD_TYPE=Release
    <span class="token punctuation">-</span> cmake <span class="token punctuation">-</span><span class="token punctuation">-</span>build build
<span class="token key atrule">test</span><span class="token punctuation">:</span>
  <span class="token key atrule">stage</span><span class="token punctuation">:</span> test
  <span class="token key atrule">script</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> ctest <span class="token punctuation">-</span><span class="token punctuation">-</span>test<span class="token punctuation">-</span>dir build <span class="token punctuation">-</span><span class="token punctuation">-</span>output<span class="token punctuation">-</span>on<span class="token punctuation">-</span>failure
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>CI 里的实用技巧</strong>：</p><ul><li>缓存 <code>build/</code> 目录以加速增量构建（GitHub Actions 的 <code>actions/cache</code>）。</li><li>把 <code>ctest</code> 失败信息带上 <code>--output-on-failure</code>，否则 CI 日志看不到断言详情。</li><li>用 <code>cmake --install build --prefix &lt;临时目录&gt;</code> 在 CI 里验证安装规则，再 <code>cpack</code> 出安装包产物（artifacts）。</li></ul><h3 id="_6-与-vcpkg-conan-配合" tabindex="-1"><a class="header-anchor" href="#_6-与-vcpkg-conan-配合" aria-hidden="true">#</a> 6. 与 vcpkg / Conan 配合</h3><p>Homebrew 之外，跨平台 C/C++ 依赖管理常用 vcpkg 或 Conan，它们与 CMake 深度集成：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># vcpkg（Windows/Linux 为主）</span>
./vcpkg <span class="token function">install</span> <span class="token function">fmt</span>
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span>/path/to/vcpkg/scripts/buildsystems/vcpkg.cmake

<span class="token comment"># Conan（跨平台）</span>
conan <span class="token function">install</span> <span class="token builtin class-name">.</span> --output-folder<span class="token operator">=</span>build <span class="token parameter variable">--build</span><span class="token operator">=</span>missing
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token punctuation">\\</span>
  <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span>build/conan_toolchain.cmake
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>presets</code> 可让一键配置更标准：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token comment">// CMakePresets.json</span>
<span class="token punctuation">{</span>
  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token number">6</span><span class="token punctuation">,</span>
  <span class="token property">&quot;configurePresets&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span>
      <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;release&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;generator&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Ninja&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;binaryDir&quot;</span><span class="token operator">:</span> <span class="token string">&quot;\${sourceDir}/build&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;cacheVariables&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;CMAKE_BUILD_TYPE&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Release&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;CMAKE_EXPORT_COMPILE_COMMANDS&quot;</span><span class="token operator">:</span> <span class="token string">&quot;ON&quot;</span>
      <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;buildPresets&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span> <span class="token punctuation">{</span> <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;release&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;configurePreset&quot;</span><span class="token operator">:</span> <span class="token string">&quot;release&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">--preset</span> release
cmake <span class="token parameter variable">--build</span> <span class="token parameter variable">--preset</span> release
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-生产级实践建议" tabindex="-1"><a class="header-anchor" href="#_7-生产级实践建议" aria-hidden="true">#</a> 7. 生产级实践建议</h3><ul><li><strong>用 target 级命令而非全局命令</strong>：优先 <code>target_include_directories</code>/<code>target_compile_options</code>/<code>target_link_libraries</code>，而不是全局 <code>include_directories</code>/<code>add_compile_options</code>。这让依赖关系显式、可移植，是现代 CMake 的核心规范。</li><li><strong>定义库目标 + <code>::</code> 命名空间别名</strong>：库导出时用 <code>add_library(foo::foo ALIAS foo)</code>，让使用者 <code>find_package</code> 后能直接 <code>target_link_libraries(app PRIVATE foo::foo)</code>，避免名字冲突。</li><li><strong>开启编译警告并尽量消除</strong>：见「5. 模块化 CMakeLists」中的 <code>enable_warnings</code> 函数，配合 <code>-Werror</code> 让 CI 把警告当错误拦截。</li><li><strong>区分共享/静态库与安装导出</strong>：用 <code>BUILD_SHARED_LIBS</code> 变量控制默认库类型：<div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token keyword">option</span><span class="token punctuation">(</span><span class="token variable">BUILD_SHARED_LIBS</span> <span class="token string">&quot;Build shared libraries&quot;</span> <span class="token boolean">ON</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><strong>做好「安装规则」</strong>：<code>install(TARGETS ...)</code>、<code>install(DIRECTORY include/ ...)</code>、<code>install(EXPORT ...)</code> 三件套，让下游能 <code>find_package</code> 到你的包。</li><li><strong>为公共库生成 <code>xxxConfig.cmake</code> 导出文件</strong>：配合 CMake 的 <code>CMakePackageConfigHelpers</code> 模块，让安装后的包可被其他 CMake 项目 <code>find_package</code>。</li></ul><h2 id="八、总结" tabindex="-1"><a class="header-anchor" href="#八、总结" aria-hidden="true">#</a> 八、总结</h2><p>CMake 的核心心智模型是**「配置阶段 + 生成阶段」**：配置阶段解析 <code>CMakeLists.txt</code> 并生成构建文件，生成阶段由底层工具（Make/Ninja/Xcode）真正编译。掌握四件事就能高效使用：</p><ol><li><strong>会写 <code>CMakeLists.txt</code></strong>——目标、依赖、安装规则三件套。</li><li><strong>会选生成器</strong>——日常用 Ninja，IDE 场景用 Xcode/VS，交叉编译用工具链文件。</li><li><strong>会管理依赖</strong>——<code>find_package</code> + <code>FetchContent</code>，配 vcpkg/Conan/brew。</li><li><strong>会自动化</strong>——CTest 测试、CPack 打包、Makefile/脚本封装、CI 集成。</li></ol><p>把这些串起来，你的 C/C++ 项目就能做到「一次编写，多平台构建，一键测试打包」，这正是 CMake 作为行业标准的价值所在。</p>`,122),l=[i];function c(o,p){return n(),s("div",null,l)}const u=a(t,[["render",c],["__file","cmake.html.vue"]]);export{u as default};
